#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY required: without it the garbage collector frees the
	// NewObject-created tracker mid-match (crash in AddPoints, see shipping log).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker* ScoreTracker was a raw UObject pointer created with NewObject but not held by a UPROPERTY, so nothing referenced it and the garbage collector destroyed it mid-match (log: 'LogGarbage: Collecting garbage: 412 objects purged' at 21.05.13). The next goal dereferenced the dangling pointer: AArenaGameMode::OnGoalScored -> UArenaScoreTracker::AddPoints (ArenaScoreTracker.cpp:18) threw EXCEPTION_ACCESS_VIOLATION reading 0xffffffffffffffff (freed-memory fill), matching the crash ~1 minute into play.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary was never cooked into the package: ProjectPackagingSettings has bCookAll=False and only cooks /Game/Maps/Arena plus /Game/Data/Effects, so /Game/Data/Palettes is missing. In the editor the asset loads from disk, but in the packaged build LoadObject fails ('Couldn't find file for package /Game/Data/Palettes/DA_Primary', 'Failed to find object ArenaPalette ...', 'Palette is null, using fallback gray'), so the HUD/arena renders in fallback gray with no colors."
}
